macro_rules! deps {
    () => {
        Type!();
        Blob!();
    };
}

macro_rules! Error {
    () => {
        deps!();
        # [doc = " Enum listing possible errors from rusqlite."] # [derive (Debug)] # [non_exhaustive] pub enum Error { # [doc = " An error from an underlying SQLite call."] SqliteFailure (ffi :: Error , Option < String >) , # [doc = " Error reported when attempting to open a connection when SQLite was"] # [doc = " configured to allow single-threaded use only."] SqliteSingleThreadedMode , # [doc = " Error when the value of a particular column is requested, but it cannot"] # [doc = " be converted to the requested Rust type."] FromSqlConversionFailure (usize , Type , Box < dyn error :: Error + Send + Sync + 'static >) , # [doc = " Error when SQLite gives us an integral value outside the range of the"] # [doc = " requested type (e.g., trying to get the value 1000 into a `u8`)."] # [doc = " The associated `usize` is the column index,"] # [doc = " and the associated `i64` is the value returned by SQLite."] IntegralValueOutOfRange (usize , i64) , # [doc = " Error converting a string to UTF-8."] Utf8Error (str :: Utf8Error) , # [doc = " Error converting a string to a C-compatible string because it contained"] # [doc = " an embedded nul."] NulError (NulError) , # [doc = " Error when using SQL named parameters and passing a parameter name not"] # [doc = " present in the SQL."] InvalidParameterName (String) , # [doc = " Error converting a file path to a string."] InvalidPath (PathBuf) , # [doc = " Error returned when an [`execute`](crate::Connection::execute) call"] # [doc = " returns rows."] ExecuteReturnedResults , # [doc = " Error when a query that was expected to return at least one row (e.g.,"] # [doc = " for [`query_row`](crate::Connection::query_row)) did not return any."] QueryReturnedNoRows , # [doc = " Error when a query that was expected to return only one row (e.g.,"] # [doc = " for [`query_one`](crate::Connection::query_one)) did return more than one."] QueryReturnedMoreThanOneRow , # [doc = " Error when the value of a particular column is requested, but the index"] # [doc = " is out of range for the statement."] InvalidColumnIndex (usize) , # [doc = " Error when the value of a named column is requested, but no column"] # [doc = " matches the name for the statement."] InvalidColumnName (String) , # [doc = " Error when the value of a particular column is requested, but the type"] # [doc = " of the result in that column cannot be converted to the requested"] # [doc = " Rust type."] InvalidColumnType (usize , String , Type) , # [doc = " Error when a query that was expected to insert one row did not insert"] # [doc = " any or insert many."] StatementChangedRows (usize) , # [doc = " Error returned by"] # [doc = " [`functions::Context::get`](crate::functions::Context::get) when the"] # [doc = " function argument cannot be converted to the requested type."] # [cfg (feature = "functions")] InvalidFunctionParameterType (usize , Type) , # [doc = " Error returned by [`vtab::Values::get`](crate::vtab::Values::get) when"] # [doc = " the filter argument cannot be converted to the requested type."] # [cfg (feature = "vtab")] InvalidFilterParameterType (usize , Type) , # [doc = " An error case available for implementors of custom user functions (e.g.,"] # [doc = " [`create_scalar_function`](crate::Connection::create_scalar_function))."] # [cfg (feature = "functions")] UserFunctionError (Box < dyn error :: Error + Send + Sync + 'static >) , # [doc = " Error available for the implementors of the"] # [doc = " [`ToSql`](crate::types::ToSql) trait."] ToSqlConversionFailure (Box < dyn error :: Error + Send + Sync + 'static >) , # [doc = " Error when the SQL is not a `SELECT`, is not read-only."] InvalidQuery , # [doc = " An error case available for implementors of custom modules (e.g.,"] # [doc = " [`create_module`](crate::Connection::create_module))."] # [cfg (feature = "vtab")] ModuleError (String) , # [doc = " An unwinding panic occurs in a UDF (user-defined function)."] UnwindingPanic , # [doc = " An error returned when"] # [doc = " [`Context::get_aux`](crate::functions::Context::get_aux) attempts to"] # [doc = " retrieve data of a different type than what had been stored using"] # [doc = " [`Context::set_aux`](crate::functions::Context::set_aux)."] # [cfg (feature = "functions")] GetAuxWrongType , # [doc = " Error when the SQL contains multiple statements."] MultipleStatement , # [doc = " Error when the number of bound parameters does not match the number of"] # [doc = " parameters in the query. The first `usize` is how many parameters were"] # [doc = " given, the 2nd is how many were expected."] InvalidParameterCount (usize , usize) , # [doc = " Returned from various functions in the Blob IO positional API. For"] # [doc = " example,"] # [doc = " [`Blob::raw_read_at_exact`](crate::blob::Blob::raw_read_at_exact) will"] # [doc = " return it if the blob has insufficient data."] # [cfg (feature = "blob")] BlobSizeError , # [doc = " Error referencing a specific token in the input SQL"] # [cfg (feature = "modern_sqlite")] SqlInputError { # [doc = " error code"] error : ffi :: Error , # [doc = " error message"] msg : String , # [doc = " SQL input"] sql : String , # [doc = " byte offset of the start of invalid token"] offset : c_int , } , # [doc = " Loadable extension initialization error"] # [cfg (feature = "loadable_extension")] InitError (ffi :: InitError) , # [doc = " Error when the schema of a particular database is requested, but the index"] # [doc = " is out of range."] # [cfg (feature = "modern_sqlite")] InvalidDatabaseIndex (usize) , }
    };
}

Error!();